    Bug 1955751 - Try to fix intermittent comm/mail/components/addrbook/test/browser/browser_drag_drop.js | Uncaught exception in test bound test_drop_on_compose. r=tobyp

    If the compose window didn't yet get set as dirty, there won't be a close-confirmation dialog.

    Differential Revision: https://phabricator.services.mozilla.com/D260967

diff --git a/mail/components/addrbook/test/browser/browser_drag_drop.js b/mail/components/addrbook/test/browser/browser_drag_drop.js
index 5464fa506d8..1d9b084052c 100644
--- a/mail/components/addrbook/test/browser/browser_drag_drop.js
+++ b/mail/components/addrbook/test/browser/browser_drag_drop.js
@@ -99,7 +99,8 @@ async function doDragToComposeWindow(sourceIndices, expectedPills) {
   Assert.ok(
     !composeDocument
       .getElementById("dropAttachmentOverlay")
-      .classList.contains("show")
+      .classList.contains("show"),
+    "#dropAttachmentOverlay should not show"
   );
   EventUtils.synthesizeDropAfterDragOver(
     result,
@@ -111,11 +112,24 @@ async function doDragToComposeWindow(sourceIndices, expectedPills) {
   dragService.getCurrentSession().endDragSession(true);

   const pills = toAddrRow.querySelectorAll("mail-address-pill");
-  Assert.equal(pills.length, expectedPills.length);
+  Assert.equal(
+    pills.length,
+    expectedPills.length,
+    "should have expected number of pills"
+  );
   for (let i = 0; i < expectedPills.length; i++) {
-    Assert.equal(pills[i].label, expectedPills[i]);
+    Assert.equal(
+      pills[i].label,
+      expectedPills[i],
+      `pill label ${i} should be correct`
+    );
   }

+  await BrowserTestUtils.waitForCondition(
+    () => composeWindow.gContentChanged,
+    "Waiting for compose window to become dirty"
+  );
+
   const promptPromise = BrowserTestUtils.promiseAlertDialog("extra1");
   composeWindow.goDoCommand("cmd_close");
   await promptPromise;
